param([Parameter(Mandatory)][string]$OutputPath,[string]$PlanPath=(Join-Path $PSScriptRoot 'numberformatinfo-invariant-provider-plan-v1.json'))
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
[Globalization.CultureInfo]::CurrentCulture=[Globalization.CultureInfo]::InvariantCulture;[Globalization.CultureInfo]::CurrentUICulture=[Globalization.CultureInfo]::InvariantCulture
$plan=Get-Content -LiteralPath $PlanPath -Raw|ConvertFrom-Json
function Decode($Spec,$Encoded){if([object]::ReferenceEquals($Encoded,$null)){$v=$null}elseif($Spec.kind -eq 'int'){$v=[int]$Encoded}elseif($Spec.kind -eq 'array'){$v=[int[]]$Encoded}else{$v=-join [char[]][int[]]$Encoded};return ,$v}
function New-Seed{$n=[Globalization.NumberFormatInfo]::new();foreach($spec in $plan.properties){[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($n,(Decode $spec $spec.seed))};return $n}
function Snapshot($N){$values=[ordered]@{};foreach($spec in $plan.properties){$v=[Globalization.NumberFormatInfo].GetProperty($spec.name).GetValue($N);if($spec.kind -eq 'string'){$values[$spec.name]=[int[]][char[]]$v}elseif($spec.kind -eq 'array'){$values[$spec.name]=[int[]]$v}else{$values[$spec.name]=[int]$v}};return [ordered]@{readOnly=$N.IsReadOnly;values=$values}}
function Failure($Record){$e=$Record.Exception;while($e -is [Reflection.TargetInvocationException] -or $e -is [Management.Automation.MethodInvocationException]){$e=$e.InnerException};return [ordered]@{ok=$false;exception=$e.GetType().FullName;messageUnits=[int[]][char[]]$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null});actualValue=$(if($e -is [ArgumentOutOfRangeException]){$e.ActualValue}else{$null})}}

$invariant=[Globalization.NumberFormatInfo]::InvariantInfo;$identity=@();for($i=0;$i -lt 64;$i++){$identity+=@([object]::ReferenceEquals($invariant,[Globalization.NumberFormatInfo]::InvariantInfo))};$snapshot=Snapshot $invariant;$fresh=[Globalization.NumberFormatInfo]::new();$freshSnapshot=Snapshot $fresh;$sameReadOnly=[object]::ReferenceEquals($invariant,[Globalization.NumberFormatInfo]::ReadOnly($invariant));$providerSelf=[object]::ReferenceEquals($invariant.GetFormat([Globalization.NumberFormatInfo]),$invariant)
$clones=[Collections.Generic.List[object]]::new()
foreach($spec in $plan.properties){try{[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($invariant,(Decode $spec $spec.invariantMutation));$mutation=[ordered]@{ok=$true}}catch{$mutation=Failure $_};$copy=[Globalization.NumberFormatInfo][ICloneable].GetMethod('Clone').Invoke($invariant,[object[]]@());$before=Snapshot $copy;[Globalization.NumberFormatInfo].GetProperty($spec.name).SetValue($copy,(Decode $spec $spec.invariantMutation));$clones.Add([ordered]@{property=$spec.name;readonlyMutation=$mutation;before=$before;after=(Snapshot $copy);invariantAfter=(Snapshot $invariant);distinct=(-not [object]::ReferenceEquals($invariant,$copy));providerSelf=[object]::ReferenceEquals($copy.GetFormat([Globalization.NumberFormatInfo]),$copy)})}
$formats=[Collections.Generic.List[object]]::new();$formatter=[IFormattable].GetMethod('ToString')
foreach($value in $plan.values){foreach($format in $plan.formats){$arguments=[object[]]::new(2);$arguments[0]=$format;$arguments[1]=$invariant;try{$text=$formatter.Invoke([int]$value,$arguments);$outcome=[ordered]@{ok=$true;textUnits=[int[]][char[]]$text}}catch{$outcome=Failure $_};$formats.Add([ordered]@{value=[int]$value;formatUnits=$(if([object]::ReferenceEquals($format,$null)){$null}else{,[int[]][char[]]$format});result=$outcome})}}
if($clones.Count -ne 22 -or $formats.Count -ne 128){throw 'Wrong invariant provider matrix'}
$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();planSha256=(Get-FileHash -LiteralPath $PlanPath -Algorithm SHA256).Hash.ToLowerInvariant();culture='Invariant';snapshot=$snapshot;fresh=$freshSnapshot;identity=$identity;sameReadOnly=$sameReadOnly;providerSelf=$providerSelf;clones=$clones.ToArray();formats=$formats.ToArray();finalSnapshot=(Snapshot $invariant);qualification='REPRESENTED_INVARIANTINFO_SEQUENTIAL_CACHE_IMMUTABILITY_CLONES_AND_INT32_PROVIDER_ONLY; FIRST_ACCESS_RACES_CURRENT_CULTURE_OTHER_FIELDS_FULL_METADATA_SERIALIZATION_AND_TASK_ACCEPTANCE_OPEN'};[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 24 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output 'PASS InvariantInfo reference: 64 identities, 22 clone cases, 128 formats'
